pseudocode:
1: let dp = new Array(m).fill(0).map(() => new Array(n).fill(0));
2: dp[0][0] = obstacleGrid[0][0] === 0 ? 1 : 0;
3: for (let i = 0; i < m; i++) {
4:   for (let j = 0; j < n; j++) {
5:     if (obstacleGrid[i][j] === 1) dp[i][j] = 0;
6:     else {
7:       if (i > 0) dp[i][j] += dp[i-1][j];
8:       if (j > 0) dp[i][j] += dp[i][j-1];
9:     }
10:  }
11: }
